describe('Login Loading Spinner', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000/login');
  });

  it('should display loading spinner while login request is processing', () => {
    cy.intercept('POST', '/api/auth/login', (req) => {
      req.reply((res) => {
        res.delay(2000);
        res.send({
          statusCode: 200,
          body: { token: 'test-token', user: { id: 1, email: 'test@example.com' } }
        });
      });
    }).as('loginRequest');

    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.get('[data-testid="loading-spinner"]').should('have.css', 'display').and('not.equal', 'none');

    cy.wait('@loginRequest');
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should hide loading spinner after successful login', () => {
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 200,
      body: { token: 'test-token', user: { id: 1, email: 'test@example.com' } }
    }).as('loginRequest');

    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@loginRequest');
    cy.get('[data-testid="loading-spinner"]').should('not.be.visible');
    cy.url().should('include', '/dashboard');
  });

  it('should hide loading spinner when login request fails', () => {
    cy.intercept('POST', '/api/auth/login', {
      statusCode: 401,
      body: { error: 'Invalid credentials' }
    }).as('loginRequest');

    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('wrongpassword');
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@loginRequest');
    cy.get('[data-testid="loading-spinner"]').should('not.be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid credentials');
  });

  it('should handle rapid submit button clicks and show spinner only once', () => {
    cy.intercept('POST', '/api/auth/login', (req) => {
      req.reply((res) => {
        res.delay(1500);
        res.send({
          statusCode: 200,
          body: { token: 'test-token', user: { id: 1, email: 'test@example.com' } }
        });
      });
    }).as('loginRequest');

    cy.get('input[name="email"]').type('test@example.com');
    cy.get('input[name="password"]').type('password123');
    cy.get('button[type="submit"]').click();
    cy.get('button[type="submit"]').click();

    cy.get('[data-testid="loading-spinner"]').should('be.visible');
    cy.wait('@loginRequest');
    cy.get('[data-testid="loading-spinner"]').should('not.be.visible');
  });
});
